```tsx
import "./StreakBadge.css";

export interface StreakBadgeProps {
  /** The current day of the streak, counted from 1. */
  day: number;
  /** The length of the whole streak, such as 66. */
  total: number;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function StreakBadge({ day, total }: StreakBadgeProps) {
  const safeTotal = Math.max(1, Math.floor(total));
  const safeDay = clamp(Math.floor(day), 0, safeTotal);
  const percent = Math.round((safeDay / safeTotal) * 100);
  const text = `Day ${safeDay} of ${safeTotal}`;

  return (
    <div
      className="streak-badge"
      role="group"
      aria-label={`Streak: ${text}`}
      tabIndex={0}
    >
      <p className="streak-badge__label">{text}</p>
      <div
        className="streak-badge__track"
        role="progressbar"
        aria-label="Streak progress"
        aria-valuemin={0}
        aria-valuemax={safeTotal}
        aria-valuenow={safeDay}
        aria-valuetext={text}
      >
        <div className="streak-badge__fill" style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
```

