  font-size: clamp(0.8rem, 1.2vw, 1rem);
}

.streak-badge:focus-visible {
  border-color: var(--cresyl);
}

.streak-badge__label {
  margin: 0;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.streak-badge__track {
  height: 0.375rem;
  overflow: hidden;
  border-radius: 999px;
  background: var(--axon-ahead);
}

.streak-badge__fill {
  height: 100%;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 0.4s ease;
